1	/**
2	 * Python's `float(str)` conversion, reimplemented for `argparse(type=float)`.
3	 *
4	 * CPython does this in two steps, and both matter:
5	 *
6	 *   1. `_PyUnicode_TransformDecimalAndSpaceToASCII` rewrites the string — ASCII is
7	 *      passed through untouched, non-ASCII whitespace collapses to a plain space,
8	 *      and any Unicode decimal digit folds to its ASCII equivalent (so `١٢٣` is a
9	 *      perfectly good `123`). Anything else non-ASCII poisons the string.
10	 *   2. `float_from_string_inner` strips *ASCII* whitespace and runs strtod.
11	 *
12	 * The split explains two behaviours a single trim would get wrong: U+00A0 is
13	 * accepted as padding (step 1 turns it into a space) while U+001C is rejected
14	 * (it is ASCII, so step 1 leaves it alone and step 2 does not consider it space).
15	 */
16	
17	/** `Py_UNICODE_ISSPACE` restricted to the non-ASCII code points, used by step 1. */
18	function isUnicodeSpace(cp) {
19	  return (
20	    cp === 0x85 ||
21	    cp === 0xa0 ||
22	    cp === 0x1680 ||
23	    (cp >= 0x2000 && cp <= 0x200a) ||
24	    cp === 0x2028 ||
25	    cp === 0x2029 ||
26	    cp === 0x202f ||
27	    cp === 0x205f ||
28	    cp === 0x3000
29	  );
30	}
31	
32	const DECIMAL_DIGIT = /\p{Nd}/u;
33	
34	/**
35	 * `Py_UNICODE_TODECIMAL`: the 0-9 value of a Unicode decimal digit, or -1.
36	 *
37	 * Every Nd run in Unicode is a whole number of consecutive 0-9 sequences, so the
38	 * value is the offset from the start of the run, modulo ten. (Verified against the
39	 * full code space: all 64 runs have a length divisible by 10.)
40	 */
41	function decimalDigitValue(ch) {
42	  if (!DECIMAL_DIGIT.test(ch)) return -1;
43	  const cp = ch.codePointAt(0);
44	  let runStart = cp;
45	  while (runStart > 0 && DECIMAL_DIGIT.test(String.fromCodePoint(runStart - 1))) runStart--;
46	  return (cp - runStart) % 10;
47	}
48	
49	/** Step 1. Returns null when a character cannot be represented in ASCII. */
50	function transformDecimalAndSpaceToASCII(text) {
51	  let out = '';
52	  for (const ch of text) {
53	    const cp = ch.codePointAt(0);
54	    if (cp < 127) {
55	      out += ch;
56	    } else if (isUnicodeSpace(cp)) {
57	      out += ' ';
58	    } else {
59	      const value = decimalDigitValue(ch);
60	      if (value < 0) return null;
61	      out += String(value);
62	    }
63	  }
64	  return out;
65	}
