67	/** `Py_ISSPACE`: the six ASCII whitespace characters strtod skips. */
68	const ASCII_SPACE = ' \t\n\v\f\r';
69	
70	function stripAsciiSpace(s) {
71	  let a = 0;
72	  let b = s.length;
73	  while (a < b && ASCII_SPACE.includes(s[a])) a++;
74	  while (b > a && ASCII_SPACE.includes(s[b - 1])) b--;
75	  return s.slice(a, b);
76	}
