78	/**
79	 * Drop PEP 515 underscores, or return null if any underscore is not flanked by
80	 * digits on both sides (`1_000` is fine, `_1`, `1_`, `1__0`, `1_.0` are not).
81	 */
82	function removeUnderscores(s) {
83	  if (!s.includes('_')) return s;
84	  for (let i = 0; i < s.length; i++) {
85	    if (s[i] !== '_') continue;
86	    const prev = s[i - 1];
87	    const next = s[i + 1];
88	    if (prev === undefined || next === undefined) return null;
89	    if (prev < '0' || prev > '9' || next < '0' || next > '9') return null;
90	  }
91	  return s.replace(/_/g, '');
92	}
