94	// digits[.digits] | .digits  — with an optional decimal exponent.
95	const DECIMAL_RE = /^(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;
96	
97	/**
98	 * Parse `text` the way CPython's `float()` does.
99	 * Returns a JS number, or null when CPython would raise ValueError.
100	 */
101	export function pyFloat(text) {
102	  const ascii = transformDecimalAndSpaceToASCII(text);
103	  if (ascii === null) return null;
104	
105	  const stripped = stripAsciiSpace(ascii);
106	  if (stripped === '') return null;
107	
108	  let sign = 1;
109	  let body = stripped;
110	  if (body[0] === '+' || body[0] === '-') {
111	    if (body[0] === '-') sign = -1;
112	    body = body.slice(1);
113	  }
114	  if (body === '') return null;
115	
116	  const lowered = body.toLowerCase();
117	  if (lowered === 'inf' || lowered === 'infinity') return sign * Infinity;
118	  if (lowered === 'nan') return sign * NaN;
119	
120	  const cleaned = removeUnderscores(body);
121	  if (cleaned === null || !DECIMAL_RE.test(cleaned)) return null;
122	
123	  // The regex has already excluded every form Number() would treat leniently
124	  // (empty string, hex, whitespace, "Infinity"), so this is a faithful strtod.
125	  return sign * Number(cleaned);
126	}
