11	const SHORT_ESCAPES = { '\t': '\\t', '\n': '\\n', '\r': '\\r', '\\': '\\\\' };
12	
13	/**
14	 * The complement of `str.isprintable()`: the Unicode categories C* and Z*,
15	 * except that a plain space is printable.
16	 */
17	const NON_PRINTABLE = /[\p{C}\p{Zl}\p{Zp}\p{Zs}]/u;
18	
19	function hexEscape(cp) {
20	  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
21	  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
22	  return '\\U' + cp.toString(16).padStart(8, '0');
23	}
24	
25	export function pyRepr(s) {
26	  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
27	  let out = quote;
28	  for (const ch of s) {
29	    if (Object.hasOwn(SHORT_ESCAPES, ch)) {
30	      out += SHORT_ESCAPES[ch];
31	    } else if (ch === quote) {
32	      out += '\\' + ch;
33	    } else if (ch !== ' ' && NON_PRINTABLE.test(ch)) {
34	      out += hexEscape(ch.codePointAt(0));
35	    } else {
36	      out += ch;
37	    }
38	  }
39	  return out + quote;
40	}
