export function groupIntegerDigits(digits) {
  const { groupSize, groupSeparator, minimumGroupingDigits } = CURRENCY_PATTERN;
  if (digits.length <= groupSize + minimumGroupingDigits - 1) return digits;

  const head = digits.length % groupSize || groupSize;
  const parts = [digits.slice(0, head)];
  for (let i = head; i < digits.length; i += groupSize) {
    parts.push(digits.slice(i, i + groupSize));
